svg.script:
//
(function() {
  const init = () => {
    const hotspots = {
      'hs-neglect': { card: 'card-neglect', guide: 'neglect-zone' },
      'hs-hands': { card: 'card-hands', guide: 'hands-glow' },
      'hs-spacing': { card: 'card-spacing', guide: 'spacing-zone' }
    };

    let currentActive = null;

    function deactivateAll() {
      Object.keys(hotspots).forEach(id => {
        const hsEl = document.getElementById(id);
        const cardEl = document.getElementById(hotspots[id].card);
        const guideEl = document.getElementById(hotspots[id].guide);
        if (hsEl) hsEl.classList.remove('active');
        if (cardEl) cardEl.classList.remove('active');
        if (guideEl) guideEl.classList.remove('active');
      });
      const defCard = document.getElementById('card-default');
      if (defCard) defCard.classList.add('active');
      currentActive = null;
    }

    function activate(id) {
      deactivateAll();
      const hsEl = document.getElementById(id);
      const cardEl = document.getElementById(hotspots[id].card);
      const guideEl = document.getElementById(hotspots[id].guide);

      if (hsEl) hsEl.classList.add('active');
      if (cardEl) cardEl.classList.add('active');
      if (guideEl) guideEl.classList.add('active');

      const defCard = document.getElementById('card-default');
      if (defCard) defCard.classList.remove('active');
      currentActive = id;
    }

    Object.keys(hotspots).forEach(id => {
      const el = document.getElementById(id);
      if (!el) return;

      // Click Interaction
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        if (currentActive === id) {
          deactivateAll();
        } else {
          activate(id);
        }
      });

      // Keyboard Accessibility
      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          if (currentActive === id) {
            deactivateAll();
          } else {
            activate(id);
          }
        }
      });

      // Hover Preview
      el.addEventListener('mouseenter', () => {
        if (!currentActive) {
          const cardEl = document.getElementById(hotspots[id].card);
          const guideEl = document.getElementById(hotspots[id].guide);
          const defCard = document.getElementById('card-default');
          if (cardEl) cardEl.classList.add('active');
          if (guideEl) guideEl.classList.add('active');
          if (defCard) defCard.classList.remove('active');
        }
      });

      el.addEventListener('mouseleave', () => {
        if (!currentActive) {
          const cardEl = document.getElementById(hotspots[id].card);
          const guideEl = document.getElementById(hotspots[id].guide);
          const defCard = document.getElementById('card-default');
          if (cardEl) cardEl.classList.remove('active');
          if (guideEl) guideEl.classList.remove('active');
          if (defCard) defCard.classList.add('active');
        }
      });
    });

    // Click canvas to clear active selection
    const svgEl = document.getElementById('clock-svg-p3');
    if (svgEl) {
      svgEl.addEventListener('click', () => {
        deactivateAll();
      });
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
//
